  'Z':'ز',  // ز (also ذ ض ظ)
  'R':'ر',  // ر (also ڑ)
  'SH':'ش', // ش
  'GH':'غ', // غ
  'F':'ف',  // ف
  'K':'ک',  // ک (also ق)
  'G':'گ',  // گ
  'L':'ل',  // ل
  'M':'م',  // م
